cd /workspace && timeout 180 python3 - <<'PY'
import sys,random,itertools,json
sys.path.insert(0,'/workspace/submission')
from netnomos.finite import compile_job
rng=random.Random(11);dom=[0,1,2,9,10,11,99,100,101,999,1000,1000000]
j={'fields':[{'name':'x','type':'id','domain':dom}],'slots':1,'predicates':[],'width':1,'train':[[[0]]],'approved':[],'queries':[]}
prefs=['']+[''.join(str(rng.randrange(10)) for _ in range(rng.randrange(1,8))) for _ in range(5000)]
j['queries']=[{'fixed':[],'target':[0,'x'],'prefix':p} for p in prefs]
r=compile_job(j)
for p,a in zip(prefs,r['answers']):
 comps=[v for v in dom if str(v).startswith(p)]
 if not comps:
  exp={'count':0,'tokens':[],'witness':None}
 else:
  ds={str(v)[len(p)] for v in comps if len(str(v))>len(p)}
  end=any(str(v)==p for v in comps)
  exp={'count':len(comps),'tokens':[str(d) for d in range(10) if str(d) in ds]+(['END'] if end else []),'witness':min(dom.index(v) for v in comps)}
 if a!=exp:
  print('FAIL',p,a,exp);break
else:print('prefix exhaustive-ish pass',len(prefs))
PY
